import{_ as a,C as o,o as i,c as s,E as t,a2 as l}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Weekly 002 — Digital Employee Control Plane and Work Runtime","description":"","frontmatter":{"title":"Weekly 002 — Digital Employee Control Plane and Work Runtime","date":"2026-08-01","column":"digital-employee","category":"weekly","summary":"A synthesis of Workday Agent System of Record, OpenHands Agent Canvas, and the engineering direction of CodeFlowMu.","outline":"deep","cover":"/assets/covers/weekly-002-cover-v2.jpg"},"headers":[],"relativePath":"en/research/weekly/weekly-002.md","filePath":"en/research/weekly/weekly-002.md","lastUpdated":1787407830000}'),r={name:"en/research/weekly/weekly-002.md"};function c(p,e,d,h,u,m){const n=o("ArticleCover");return i(),s("div",null,[t(n,{image:"/assets/covers/weekly-002-cover-v2.jpg",kicker:"Weekly Research · 002",title:"Digital Employee Control Plane and Work Runtime",summary:"A synthesis of Workday Agent System of Record, OpenHands Agent Canvas, and the engineering direction of CodeFlowMu.",version:"W002",status:"Published 2026-08-01",languageHref:"/zh/research/weekly/weekly-002",languageLabel:"简体中文"}),e[0]||(e[0]=l(`<h2 id="executive-synthesis" tabindex="-1">Executive synthesis <a class="header-anchor" href="#executive-synthesis" aria-label="Permalink to &quot;Executive synthesis&quot;">​</a></h2><p>The second weekly report moves from defining a Digital Employee to separating two system layers:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Digital Employee Control Plane</span></span>
<span class="line"><span>  identity, ownership, Position, authority, Registry,</span></span>
<span class="line"><span>  lifecycle, policy, cost, telemetry and evaluation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Digital Employee Work Runtime</span></span>
<span class="line"><span>  WorkOrder, planning, workflow, sessions, tools,</span></span>
<span class="line"><span>  checkpoint, recovery, evidence and completion</span></span></code></pre></div><p>Enterprise platforms tend to provide strong workforce control but depend on heavy infrastructure. Agent frameworks provide execution primitives but usually lack organizational ownership, completion authority and lifecycle governance. CodeFlowMu should connect a lightweight control plane to its existing work runtime.</p><h2 id="workday-as-the-control-plane-benchmark" tabindex="-1">Workday as the control-plane benchmark <a class="header-anchor" href="#workday-as-the-control-plane-benchmark" aria-label="Permalink to &quot;Workday as the control-plane benchmark&quot;">​</a></h2><p>Workday Agent System of Record treats Agents as governed enterprise resources. The important fields are not only model name and prompt, but also:</p><ul><li>organizational owner;</li><li>role and skills;</li><li>authority and data access;</li><li>provider and deployment;</li><li>usage, telemetry and work history;</li><li>cost and value;</li><li>compliance and lifecycle.</li></ul><p>The engineering lesson is persistent identity. A Digital Employee must survive provider changes, temporary sessions and individual runs.</p><h2 id="openhands-as-the-operator-workspace-benchmark" tabindex="-1">OpenHands as the operator-workspace benchmark <a class="header-anchor" href="#openhands-as-the-operator-workspace-benchmark" aria-label="Permalink to &quot;OpenHands as the operator-workspace benchmark&quot;">​</a></h2><p>OpenHands Agent Canvas demonstrates the operational layer required around an Agent:</p><ul><li>visible skills and plugins;</li><li>connection-health diagnostics;</li><li>startup and runtime logs;</li><li>local, remote and hosted execution;</li><li>manual, scheduled and event-triggered automation;</li><li>an operator-facing workspace.</li></ul><p>CodeFlowMu should learn these mechanisms without changing its primary abstraction from Position to generic Agent workspace.</p><h2 id="target-architecture-for-codeflowmu" tabindex="-1">Target architecture for CodeFlowMu <a class="header-anchor" href="#target-architecture-for-codeflowmu" aria-label="Permalink to &quot;Target architecture for CodeFlowMu&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Organization</span></span>
<span class="line"><span>    ↓ defines</span></span>
<span class="line"><span>Position</span></span>
<span class="line"><span>    ↓ registered in</span></span>
<span class="line"><span>Digital Employee Control Plane</span></span>
<span class="line"><span>    ↓ issues</span></span>
<span class="line"><span>WorkOrder</span></span>
<span class="line"><span>    ↓ executed by</span></span>
<span class="line"><span>CodeFlowMu Work Runtime</span></span>
<span class="line"><span>    ↓ uses</span></span>
<span class="line"><span>Agent Providers + Tools + Rules + Humans</span></span>
<span class="line"><span>    ↓ produces</span></span>
<span class="line"><span>TMPA / FCoP governed Outcome</span></span></code></pre></div><h3 id="control-plane" tabindex="-1">Control plane <a class="header-anchor" href="#control-plane" aria-label="Permalink to &quot;Control plane&quot;">​</a></h3><ul><li>PositionRegistry;</li><li>DigitalEmployeeRegistry;</li><li>ownership and organizational placement;</li><li>TeamPolicy and authority;</li><li>provider, tool and credential bindings;</li><li>lifecycle and version;</li><li>cost, SLA and evaluation records;</li><li>compliance and audit views.</li></ul><h3 id="work-runtime" tabindex="-1">Work runtime <a class="header-anchor" href="#work-runtime" aria-label="Permalink to &quot;Work runtime&quot;">​</a></h3><ul><li>PM as the current Work Manager;</li><li>WorkOrder, Plan and Workflow;</li><li>Operation Nodes;</li><li>SessionManager and TaskDispatcher;</li><li>Browser, Windows, Source and API tools;</li><li>checkpoint, retry and recovery;</li><li>Event Outbox and TMPA projection;</li><li>FCoP coordination;</li><li>business and publication completion gates.</li></ul><h2 id="sme-first-constraint" tabindex="-1">SME-first constraint <a class="header-anchor" href="#sme-first-constraint" aria-label="Permalink to &quot;SME-first constraint&quot;">​</a></h2><p>The goal is not to reproduce an enterprise AI control tower. The minimum coherent product should remain local-first or small-service deployable, provider-independent, cost-aware, human-governed and capable of exporting evidence.</p><h2 id="recommended-engineering-sequence" tabindex="-1">Recommended engineering sequence <a class="header-anchor" href="#recommended-engineering-sequence" aria-label="Permalink to &quot;Recommended engineering sequence&quot;">​</a></h2><ol><li>Project the current Open Dev Team as the first registered Digital Employee.</li><li>Add owner, Position, version, provider, allowed tools, lifecycle state and cost policy as a read-only Registry projection.</li><li>Keep current PM/FCoP/Runtime behavior unchanged while the projection is validated.</li><li>Unify provider, tool, session, HOLD and recovery health in one console.</li><li>Validate the model with the Saige short-rental Digital Employee before building a full Studio.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The emerging system category is not “a framework with more Agents.” It is:</p><blockquote><p><strong>A governed workforce control plane connected to a reliable AI work runtime.</strong></p></blockquote><p>CodeFlowMu’s opportunity is to implement the lightweight, engineering-driven SME version of this category.</p>`,26))])}const k=a(r,[["render",c]]);export{y as __pageData,k as default};
